1: import { useState } from 'react';
2: import { motion, useReducedMotion } from 'framer-motion';
3: import { AlertCircle, Check, Copy, Clock } from 'lucide-react';
4: import type { StreamMessage } from '@/types';
5: import { Message } from '@/components/ui/c-message-3-utils/message';
6: import { Bubble, BubbleContent } from '@/components/ui/c-message-3-utils/bubble';
7: import { MarkdownContent } from './MarkdownContent';
8: import { ThinkingCapsule } from './ThinkingCapsule';
9: import { useRunSteps } from '@/queries/runs';
10: 
11: interface Props {
12:   message: StreamMessage;
13:   /** Set when this message opens a new day, rendered as a labelled divider. */
14:   divider?: string;
15:   /**
16:    * 0 keeps the entry instant; N staggers the pop, so a thread opened from
17:    * cold bounces in sequence instead of landing as one slab.
18:    */
19:   staggerIndex?: number;
20: }
21: 
22: const metaTime = (iso: string): string =>
23:   new Date(iso).toLocaleTimeString(undefined, {
24:     hour: 'numeric',
25:     minute: '2-digit',
26:   });
27: 
28: const enterSpring = {
29:   type: 'spring' as const,
30:   stiffness: 420,
31:   damping: 26,
32:   mass: 0.9,
33: };
34: 
35: /** Inline 4-point Vigil spark SVG mark (zero emoji, crisp at 14px). */
36: export function VigilSpark({ className = '' }: { className?: string }) {
37:   return (
38:     <svg
39:       viewBox="0 0 16 16"
40:       fill="currentColor"
41:       aria-hidden="true"
42:       className={`h-3.5 w-3.5 shrink-0 ${className}`}
43:     >
44:       <path d="M8 1C8.55 4.6 11.4 7.45 15 8C11.4 8.55 8.55 11.4 8 15C7.45 11.4 4.6 8.55 1 8C4.6 7.45 7.45 4.6 8 1Z" />
45:     </svg>
46:   );
47: }
48: 
49: export function MessageItem({ message, divider, staggerIndex = 0 }: Props) {
50:   const mine = message.role === 'user';
51:   const time = metaTime(message.created_at);
52:   const reduced = useReducedMotion();
53:   const delay = staggerIndex * 0.05;
54: 
55:   const [copied, setCopied] = useState(false);
56: 
57:   // Fetch steps when run_id exists so the thinking capsule can be toggled or show delivered docs
58:   const runStepsQuery = useRunSteps(message.run_id ? message.run_id : null);
59:   const mappedSteps = (runStepsQuery.data ?? [])
60:     .filter((s) => s.event_type !== 'message_delta')
61:     .map((s) => ({
62:       run_id: s.run_id,
63:       step_number: s.step_number,
64:       event_type: s.event_type,
65:       payload: s.payload,
66:       created_at: s.created_at,
67:     }));
68: 
69:   const hasSemanticSteps = mappedSteps.some(
70:     (s) => s.event_type !== 'run_completed' && s.event_type !== 'run_failed',
71:   );
72: 
73:   const handleCopy = async () => {
74:     try {
75:       await navigator.clipboard.writeText(message.content);
76:       setCopied(true);
77:       setTimeout(() => setCopied(false), 2000);
78:     } catch {
79:       const textarea = document.createElement('textarea');
80:       textarea.value = message.content;
81:       document.body.appendChild(textarea);
82:       textarea.select();
83:       document.execCommand('copy');
84:       document.body.removeChild(textarea);
85:       setCopied(true);
86:       setTimeout(() => setCopied(false), 2000);
87:     }
88:   };
89: 
90:   return (
91:     <motion.div
92:       initial={reduced ? { opacity: 0 } : { opacity: 0, y: 14 }}
93:       animate={{ opacity: 1, y: 0 }}
94:       transition={reduced ? { duration: 0.2 } : { ...enterSpring, delay }}
95:       className="w-full max-w-full min-w-0 space-y-2"
96:     >
97:       {divider ? <Divider label={divider} /> : null}
98: 
99:       {mine ? (
100:         /* ── USER MESSAGE: Tactile right-aligned pill ────────────────────── */
101:         <Message align="end" className="min-w-0 max-w-full">
102:           <div className="group flex min-w-0 max-w-[85%] flex-col items-end gap-1 sm:max-w-[76%]">
103:             <motion.div
104:               initial={reduced ? {} : { scale: 0.94 }}
105:               animate={{ scale: 1 }}
106:               transition={reduced ? { duration: 0.2 } : { ...enterSpring, delay: delay + 0.03 }}
107:               className="min-w-0 max-w-full"
108:               style={{ transformOrigin: 'bottom right' }}
109:             >
110:               <Bubble variant="default">
111:                 <BubbleContent>
112:                   <span className="block whitespace-pre-wrap [overflow-wrap:anywhere]">
113:                     {message.content}
114:                   </span>
115:                 </BubbleContent>
116:               </Bubble>
117:             </motion.div>
118: 
119:             {message.local_state === 'failed' && message.failure_reason ? (
120:               <div className="mt-1 flex items-center gap-1.5 text-[12px] text-rose-400">
121:                 <AlertCircle size={13} strokeWidth={1.75} className="shrink-0" />
122:                 <span className="[overflow-wrap:anywhere]">{message.failure_reason}</span>
123:               </div>
124:             ) : null}
125: 
126:             <div className="flex items-center gap-2 px-1 text-[11px] text-[var(--text-muted)] opacity-0 transition-opacity duration-200 group-hover:opacity-100 focus-within:opacity-100">
127:               {message.local_state === 'sending' ? (
128:                 <span className="inline-flex items-center gap-1">
129:                   <Clock size={11} strokeWidth={1.5} />
130:                   Sending
131:                 </span>
132:               ) : (
133:                 <span className="tabular-nums">{time}</span>
134:               )}
135:               <span>·</span>
136:               <button
137:                 type="button"
138:                 onClick={handleCopy}
139:                 aria-label={copied ? 'Copied message' : 'Copy message'}
140:                 className="inline-flex cursor-pointer items-center gap-1 rounded-[5px] px-1.5 py-0.5 font-medium text-[var(--text-muted)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)]"
141:               >
142:                 {copied ? (
143:                   <>
144:                     <Check size={11} strokeWidth={2} className="text-emerald-400" />
145:                     <span className="text-emerald-400">Copied</span>
146:                   </>
147:                 ) : (
148:                   <>
149:                     <Copy size={11} strokeWidth={1.5} />
150:                     <span>Copy</span>
151:                   </>
152:                 )}
153:               </button>
154:             </div>
155:           </div>
156:         </Message>
157:       ) : (
158:         /* ── VIGIL REPLY: Unboxed editorial typography + thinking deck ──── */
159:         <Message align="start" className="min-w-0 max-w-full">
160:           <div className="group flex w-full max-w-full min-w-0 flex-col items-start">
161:             {/* Editorial Header */}
162:             <div className="mb-1.5 flex w-full items-center gap-2">
163:               <span className="flex h-5 w-5 items-center justify-center rounded-full bg-[color-mix(in_srgb,var(--text)_9%,transparent)] text-[var(--text)]">
164:                 <VigilSpark />
165:               </span>
166:               <span className="text-[13px] font-semibold tracking-[-0.01em] text-[var(--text)]">
167:                 Vigil
168:               </span>
169:               <span className="text-[11px] font-medium tabular-nums text-[var(--text-muted)] opacity-0 transition-opacity duration-200 group-hover:opacity-100">
170:                 {time}
171:               </span>
172:             </div>
173: 
174:             {/* Thinking Capsule (collapsed pill by default on completed turns, expandable on click) */}
175:             {message.run_id && hasSemanticSteps ? (
176:               <div className="mb-2.5 w-full max-w-full min-w-0 pl-0 sm:pl-7">
177:                 <ThinkingCapsule
178:                   active={runStepsQuery.isLoading}
179:                   steps={mappedSteps}
180:                   defaultOpen={false}
181:                 />
182:               </div>
183:             ) : null}
184: 
185:             {/* Unboxed Editorial Markdown Surface */}
186:             <div className="w-full max-w-full min-w-0 pl-0 sm:pl-7">
187:               <MarkdownContent content={message.content} />
188:             </div>
189: 
190:             {/* Subtle Footer Actions */}
191:             <div className="mt-2 flex items-center gap-2 pl-0 sm:pl-7 text-[11px] opacity-0 transition-opacity duration-200 group-hover:opacity-100 focus-within:opacity-100">
192:               <button
193:                 type="button"
194:                 onClick={handleCopy}
195:                 aria-label={copied ? 'Copied response' : 'Copy response'}
196:                 className="inline-flex cursor-pointer items-center gap-1.5 rounded-[6px] px-2 py-1 font-medium text-[var(--text-muted)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)]"
197:               >
198:                 {copied ? (
199:                   <>
200:                     <Check size={12} strokeWidth={2} className="text-emerald-400" />
201:                     <span className="text-emerald-400">Copied response</span>
202:                   </>
203:                 ) : (
204:                   <>
205:                     <Copy size={12} strokeWidth={1.5} />
206:                     <span>Copy</span>
207:                   </>
208:                 )}
209:               </button>
210:             </div>
211:           </div>
212:         </Message>
213:       )}
214:     </motion.div>
215:   );
216: }
217: 
218: function Divider({ label }: { label: string }) {
219:   return (
220:     <div className="flex items-center gap-4 py-2 text-[11px] font-medium uppercase tracking-[0.08em] text-[var(--text-muted)]">
221:       <span className="h-px flex-1 bg-[var(--border)]" />
222:       <span>{label}</span>
223:       <span className="h-px flex-1 bg-[var(--border)]" />
224:     </div>
225:   );
226: }
227: 
228: export default MessageItem;

