72: interface RequestInit_ {
73:   method?: 'GET' | 'POST' | 'PATCH' | 'PUT' | 'DELETE';
74:   body?: unknown;
75:   query?: Record<string, string | number | boolean | undefined>;
76:   /** Required for any mutating request. Identifies the logical user action, not the attempt. */
77:   scope?: string;
78:   signal?: AbortSignal;
79: }
80: 
81: function buildUrl(path: string, query?: RequestInit_['query']): string {
82:   const url = `${BASE}${path}`;
83:   if (!query) return url;
84:   const params = new URLSearchParams();
85:   for (const [key, value] of Object.entries(query)) {
86:     if (value === undefined) continue;
87:     params.set(key, String(value));
88:   }
89:   const qs = params.toString();
90:   return qs ? `${url}?${qs}` : url;
91: }
92: 
93: function parseJson(text: string): unknown {
94:   try {
95:     return JSON.parse(text) as unknown;
96:   } catch {
97:     return null;
98:   }
99: }
100: 
101: async function request<T>(path: string, init: RequestInit_ = {}): Promise<T> {
102:   const method = init.method ?? 'GET';
103:   const isMutating = method !== 'GET';
104: 
105:   const headers: Record<string, string> = { Accept: 'application/json' };
106:   if (init.body !== undefined) headers['Content-Type'] = 'application/json';
107:   if (bearerToken) headers['Authorization'] = `Bearer ${bearerToken}`;
108: 
109:   if (isMutating) {
110:     // Frontend policy, not a backend contract: the idempotency middleware only manages requests
111:     // that carry the header, it never rejects a request for missing one. The backend enforces
112:     // replay, lock conflicts (409) and key validation (422) for managed requests only.
113:     if (!init.scope) {
114:       throw new Error(
115:         `Mutating request ${method} ${path} requires an idempotency scope. ` +
116:           'The frontend refuses to send an untracked mutation.',
117:       );
118:     }
119:     headers['Idempotency-Key'] = idempotencyKey(init.scope);
120:   }
121: 
122:   let response: Response;
123:   try {
124:     response = await fetch(buildUrl(path, init.query), {
125:       method,
126:       headers,
127:       body: init.body === undefined ? undefined : JSON.stringify(init.body),
128:       ...(init.signal ? { signal: init.signal } : {}),
129:     });
130:   } catch (error) {
131:     if (error instanceof DOMException && error.name === 'AbortError') throw error;
132:     throw new NetworkError(error instanceof Error ? error.message : 'Network request failed');
133:   }
134: 
135:   if (response.status === 204) return undefined as T;
136: 
137:   const text = await response.text();
138:   const payload = text ? parseJson(text) : null;
139: 
140:   if (!response.ok) {
141:     const envelope =
142:       payload && typeof payload === 'object' ? (payload as Record<string, unknown>) : null;
143: 
144:     if (response.status === 401) {
145:       notifyAuthFailure();
146:       throw new AuthError(401, envelope as never);
147:     }
148:     throw new ApiError(response.status, envelope as never);
149:   }
150: 
151:   return payload as T;
152: }
