64:  * (or fallback to the earliest unpaired tool_call of the same tool_name), and filter
65:  * out the final answer thought so it isn't duplicated inside the thinking trace.
66:  */
67: function buildTimeline(steps: RunStepEvent[]): TimelineItem[] {
68:   const items: TimelineItem[] = [];
69:   const toolIndexById = new Map<string, number>();
70:   const openToolIndicesByName = new Map<string, number[]>();
71: 
72:   for (let i = 0; i < steps.length; i += 1) {
73:     const step = steps[i];
74:     if (!step) continue;
75: 
76:     if (
77:       step.event_type === 'message_delta' ||
78:       step.event_type === 'run_completed' ||
79:       step.event_type === 'run_failed'
80:     ) {
81:       continue;
82:     }
83: 
84:     if (step.event_type === 'thought') {
85:       const content =
86:         typeof step.payload.content === 'string'
87:           ? step.payload.content.trim()
88:           : typeof step.payload.text === 'string'
89:             ? step.payload.text.trim()
90:             : '';
91:       const stage = typeof step.payload.stage === 'string' ? step.payload.stage : '';
92: 
93:       // If this thought has no tool_calls attached and no tool_call follows it,
94:       // it is the final assistant answer (already rendered in the main message stream).
95:       const toolCallIds = Array.isArray(step.payload.tool_call_ids)
96:         ? step.payload.tool_call_ids
97:         : null;
98:       const hasSubsequentTool = steps
99:         .slice(i + 1)
100:         .some((s) => s.event_type === 'tool_call' || s.event_type === 'tool_result');
101:       if (toolCallIds && toolCallIds.length === 0 && !hasSubsequentTool) {
102:         continue;
103:       }
104: 
105:       if (!content && stage !== 'compact_check') continue;
106: 
107:       // Avoid consecutive identical reasoning lines
108:       const prev = items[items.length - 1];
109:       if (prev && prev.kind === 'thought') {
110:         const prevContent =
111:           typeof prev.step.payload.content === 'string'
112:             ? prev.step.payload.content.trim()
113:             : typeof prev.step.payload.text === 'string'
114:               ? prev.step.payload.text.trim()
115:               : '';
116:         if (prevContent && prevContent === content) continue;
117:       }
118: 
119:       items.push({
120:         kind: 'thought',
121:         id: `thought-${step.step_number}-${i}`,
122:         stepNumber: step.step_number,
123:         step,
124:         createdAt: step.created_at,
125:       });
126:       continue;
127:     }
128: 
129:     if (step.event_type === 'tool_call') {
130:       const callId =
131:         typeof step.payload.tool_call_id === 'string'
132:           ? step.payload.tool_call_id
133:           : `call-${step.step_number}-${i}`;
134:       const toolName = String(step.payload.tool_name ?? 'tool');
135:       const args =
136:         typeof step.payload.arguments === 'object' && step.payload.arguments !== null
137:           ? (step.payload.arguments as Record<string, unknown>)
138:           : {};
139:       const partition =
140:         typeof step.payload.partition === 'string' ? step.payload.partition : undefined;
141: 
142:       const idx = items.length;
143:       items.push({
144:         kind: 'tool',
145:         id: callId,
146:         stepNumber: step.step_number,
147:         toolName,
148:         arguments: args,
149:         partition,
150:         createdAt: step.created_at,
151:       });
152: 
153:       toolIndexById.set(callId, idx);
154:       const list = openToolIndicesByName.get(toolName) ?? [];
155:       list.push(idx);
156:       openToolIndicesByName.set(toolName, list);
157:       continue;
158:     }
159: 
160:     if (step.event_type === 'tool_result') {
161:       const callId =
162:         typeof step.payload.tool_call_id === 'string' ? step.payload.tool_call_id : null;
163:       const toolName = String(step.payload.tool_name ?? 'tool');
