170:         if (candidates && candidates.length > 0) {
171:           targetIdx = candidates.shift();
172:         }
173:       } else {
174:         const candidates = openToolIndicesByName.get(toolName);
175:         if (candidates) {
176:           const pos = candidates.indexOf(targetIdx);
177:           if (pos !== -1) candidates.splice(pos, 1);
178:         }
179:       }
180: 
181:       if (targetIdx !== undefined) {
182:         const existing = items[targetIdx];
183:         if (existing && existing.kind === 'tool') {
184:           existing.resultStep = step;
185:           continue;
186:         }
187:       }
