72: interface RequestInit_ {
73:   method?: 'GET' | 'POST' | 'PATCH' | 'PUT' | 'DELETE';
74:   body?: unknown;
75:   query?: Record<string, string | number | boolean | undefined>;
76:   /** Required for any mutating request. Identifies the logical user action, not the attempt. */
77:   scope?: string;
78:   signal?: AbortSignal;
79: }
