983:   }
984: 
985:   if (item.kind === 'approval_required') {
986:     return (
987:       <div className="flex items-center gap-2 rounded-[10px] border border-amber-500/25 bg-amber-500/8 px-3 py-2 text-[12px] text-amber-200">
988:         <span>Waiting on your approval to execute external action</span>
989:       </div>
990:     );
991:   }
992: 
993:   if (item.kind !== 'tool') {
994:     return (
995:       <div className="py-0.5 text-[12px] text-[var(--text-muted)]">
996:         Context history compacted
997:       </div>
998:     );
999:   }
1000: 
1001:   const { toolName } = item;
1002:   if (toolName === 'bash') {
1003:     return <CommandExecutionCard item={item} active={active} />;
1004:   }
1005:   if (toolName === 'read' || toolName === 'write' || toolName === 'edit') {
1006:     return <FileOperationCard item={item} active={active} />;
1007:   }
1008:   if (toolName === 'deliver_file' || toolName === 'generate_document') {
1009:     return <SandboxDocumentCard item={item} active={active} />;
1010:   }
1011:   if (
1012:     toolName === 'web_search' ||
1013:     toolName === 'web_fetch' ||
1014:     toolName.startsWith('exa_') ||
1015:     toolName.includes('search')
1016:   ) {
1017:     return <WebSearchCard item={item} active={active} />;
1018:   }
1019: 
1020:   return <GenericToolCard item={item} active={active} />;
1021: }
