1023: export function ThinkingCapsule({ active, steps = [], summary, defaultOpen }: Props) {
1024:   const items = useMemo(() => buildTimeline(steps), [steps]);
1025:   const [open, setOpen] = useState<boolean>(defaultOpen ?? active);
1026: 
1027:   if (!active && items.length === 0) return null;
1028: 
1029:   const toolCount = items.filter((i) => i.kind === 'tool').length;
1030:   const deliveredDocs = items.filter(
1031:     (i): i is PairedToolItem =>
1032:       i.kind === 'tool' &&
1033:       (i.toolName === 'deliver_file' || i.toolName === 'generate_document') &&
1034:       Boolean(i.resultStep),
1035:   );
1036: 
1037:   const latestItem = items[items.length - 1];
1038: 
1039:   let displaySummary = summary;
1040:   if (!displaySummary) {
1041:     if (active) {
1042:       if (latestItem?.kind === 'tool' && !latestItem.resultStep) {
1043:         if (latestItem.toolName === 'bash') {
1044:           const cmd =
1045:             typeof latestItem.arguments.command === 'string'
1046:               ? latestItem.arguments.command.slice(0, 42)
1047:               : 'command';
1048:           displaySummary = `Running $ ${cmd}${cmd.length >= 42 ? '…' : ''}`;
1049:         } else if (
1050:           latestItem.toolName === 'deliver_file' ||
1051:           latestItem.toolName === 'generate_document'
1052:         ) {
1053:           displaySummary = 'Preparing document...';
1054:         } else {
1055:           displaySummary = `Running ${latestItem.toolName.replace(/_/g, ' ')}...`;
1056:         }
1057:       } else {
1058:         displaySummary =
1059:           items.length > 0 ? `Working through ${items.length} steps...` : 'Thinking...';
1060:       }
1061:     } else {
1062:       displaySummary =
1063:         toolCount > 0
1064:           ? `Executed ${toolCount} ${toolCount === 1 ? 'action' : 'actions'}`
1065:           : 'Thought process';
1066:     }
1067:   }
1068: 
1069:   return (
1070:     <div className="my-1.5 w-full max-w-2xl min-w-0" role="status" aria-live="polite">
1071:       {/* Clean, low-profile toggle pill */}
1072:       <button
1073:         type="button"
1074:         onClick={() => setOpen((o) => !o)}
1075:         aria-expanded={open}
1076:         className="group inline-flex max-w-full cursor-pointer items-center gap-2 rounded-full border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_3.5%,transparent)] px-3 py-1.5 text-left text-[12.5px] font-medium text-[var(--text-muted)] transition-colors hover:border-[var(--border-strong)] hover:text-[var(--text)]"
1077:       >
1078:         {active ? (
1079:           <RotateCw size={12} strokeWidth={2} className="shrink-0 animate-spin text-[var(--text)]" />
1080:         ) : (
1081:           <Sparkles size={12} strokeWidth={1.75} className="shrink-0 text-[var(--text-muted)] transition-colors group-hover:text-[var(--text)]" />
1082:         )}
1083: 
1084:         <span className="truncate">{displaySummary}</span>
1085: 
1086:         {items.length > 0 ? (
1087:           <motion.span
1088:             animate={{ rotate: open ? 180 : 0 }}
1089:             transition={spring}
1090:             className="flex shrink-0 items-center justify-center text-[var(--text-muted)]"
1091:           >
1092:             <ChevronDown size={13} strokeWidth={1.75} />
1093:           </motion.span>
1094:         ) : null}
1095:       </button>
1096: 
1097:       {/* Clean Left-Rail Timeline (no heavy outer box) */}
1098:       <AnimatePresence initial={false}>
1099:         {open && items.length > 0 ? (
1100:           <motion.div
1101:             initial={{ height: 0, opacity: 0 }}
1102:             animate={{ height: 'auto', opacity: 1 }}
1103:             exit={{ height: 0, opacity: 0 }}
1104:             transition={{ duration: 0.22, ease: [0.25, 1, 0.5, 1] }}
1105:             className="overflow-hidden"
1106:           >
1107:             <ol className="relative mt-2.5 ml-3 space-y-2.5 border-l border-[var(--border)] pl-4">
1108:               {items.map((item) => (
1109:                 <li key={item.id} className="relative min-w-0">
1110:                   {/* Timeline Node Icon sitting cleanly on the left rail */}
1111:                   <span
1112:                     aria-hidden="true"
1113:                     className="absolute -left-[25px] top-1.5 flex h-[18px] w-[18px] items-center justify-center rounded-full border border-[var(--border)] bg-[var(--surface-solid)]"
1114:                   >
1115:                     {getTimelineNodeIcon(item)}
1116:                   </span>
1117: 
1118:                   {renderTimelineItem(item, active)}
1119:                 </li>
1120:               ))}
1121:             </ol>
1122:           </motion.div>
1123:         ) : null}
1124:       </AnimatePresence>
1125: 
1126:       {/* When collapsed, still surface any delivered sandbox documents */}
1127:       {!open && deliveredDocs.length > 0 ? (
1128:         <div className="mt-2 space-y-2">
1129:           {deliveredDocs.map((doc) => (
1130:             <SandboxDocumentCard key={`Pinned-${doc.id}`} item={doc} active={false} />
1131:           ))}
1132:         </div>
1133:       ) : null}
1134:     </div>
1135:   );
1136: }
